/* ============================================================
   Rechtliches und Produktangaben
   ------------------------------------------------------------
   Die Texte sind GERUESTE, keine fertigen Rechtstexte. Sie nennen
   vollstaendig, was hineingehoert, und markieren jede Stelle, die
   ausgefuellt werden muss. Vor einer Veroeffentlichung gehoert das
   Ergebnis einmal vor fachkundige Augen.
   ============================================================ */
var rechtTab = 'impressum';
function setzeRecht(t){ rechtTab = t; renderContent(); }

function luecke(was){
  return '<mark class="luecke">' + esc(was) + '</mark>';
}

